class Solution {
    public TreeNode mergeTrees(TreeNode root1, TreeNode root2) {
        if (root1 == null) {
            return cloneTree(root2);
        }
        if (root2 == null) {
            return cloneTree(root1);
        }

        TreeNode merged = new TreeNode(root1.val + root2.val);
        merged.left = mergeTrees(root1.left, root2.left);
        merged.right = mergeTrees(root1.right, root2.right);
        return merged;
    }

    private TreeNode cloneTree(TreeNode node) {
        if (node == null) {
            return null;
        }
        TreeNode copy = new TreeNode(node.val);
        copy.left = cloneTree(node.left);
        copy.right = cloneTree(node.right);
        return copy;
    }
}

class Solution {
    public TreeNode mergeTrees(TreeNode root1, TreeNode root2) {
        if (root1 == null) {
            return root2;
        }
        if (root2 == null) {
            return root1;
        }

        root1.val += root2.val;
        root1.left = mergeTrees(root1.left, root2.left);
        root1.right = mergeTrees(root1.right, root2.right);
        return root1;
    }
}

class Solution {
    public TreeNode mergeTrees(TreeNode root1, TreeNode root2) {
        if (root1 == null) {
            return root2;
        }
        if (root2 == null) {
            return root1;
        }

        java.util.Queue<TreeNode[]> queue = new java.util.ArrayDeque<>();
        queue.offer(new TreeNode[]{root1, root2});

        while (!queue.isEmpty()) {
            TreeNode[] pair = queue.poll();
            TreeNode first = pair[0];
            TreeNode second = pair[1];
            first.val += second.val;

            if (first.left != null && second.left != null) {
                queue.offer(new TreeNode[]{first.left, second.left});
            } else if (first.left == null) {
                first.left = second.left;
            }

            if (first.right != null && second.right != null) {
                queue.offer(new TreeNode[]{first.right, second.right});
            } else if (first.right == null) {
                first.right = second.right;
            }
        }

        return root1;
    }
}
